package com.mendes.scheduling_platform.subscription; import jakarta.persistence.*; import lombok.*; import java.time.*;
@Entity @Table(name="subscriptions") @Getter @Setter @NoArgsConstructor public class Subscription { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(unique=true) private Long tenantId; private String plan; @Enumerated(EnumType.STRING) private Status status=Status.TRIAL; private LocalDate startDate; private LocalDate endDate; public enum Status { ACTIVE, TRIAL, PAST_DUE, CANCELLED, EXPIRED } }
